import csv
iodine_atoms = ['TR110_2', 'TR110_3', 'TR110_4', 'TR340_26', 'TR340_44', 'TR340_8']
bond_counts = {atom: 0 for atom in iodine_atoms}

with open('csv/connected.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        if row['atom_id'] in iodine_atoms:
            bond_counts[row['atom_id']] += 1

for atom, count in bond_counts.items():
    print(f"{atom}: {count} bonds")

print(f"Total bonds: {sum(bond_counts.values())}")
print(f"Average: {sum(bond_counts.values())/len(bond_counts)}")

